CREATE TABLE "User" ("id" SERIAL PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "username" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "bio" TEXT NOT NULL DEFAULT '', "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY, "userId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE TABLE "Chat" ("id" SERIAL PRIMARY KEY, "pairKey" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Member" ("chatId" INTEGER NOT NULL REFERENCES "Chat"("id") ON DELETE CASCADE, "userId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, PRIMARY KEY ("chatId","userId"));
CREATE TABLE "Message" ("id" SERIAL PRIMARY KEY, "chatId" INTEGER NOT NULL REFERENCES "Chat"("id") ON DELETE CASCADE, "senderId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "text" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Message_chatId_id_idx" ON "Message"("chatId","id");
